import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 4821,
  },
});

import express from 'express';
import { createServer as createViteServer } from 'vite';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PORT = 4821;

const app = express();
app.use(express.json());

// ---- In-memory todo store ----
let todos = [];
let nextId = 1;

// ---- API routes ----
app.get('/api/todos', (req, res) => {
  res.status(200).json(todos);
});

app.post('/api/todos', (req, res) => {
  const text = typeof req.body?.text === 'string' ? req.body.text : '';
  const todo = { id: nextId++, text, completed: false };
  todos.push(todo);
  res.status(201).json(todo);
});

// ---- Vite dev server as middleware (serves the React frontend) ----
const vite = await createViteServer({
  root: __dirname,
  server: { middlewareMode: true },
  appType: 'custom',
});

app.use(vite.middlewares);

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});

import React from 'react';
import { createRoot } from 'react-dom/client';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import App from './App.jsx';

const queryClient = new QueryClient();

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <QueryClientProvider client={queryClient}>
      <App />
    </QueryClientProvider>
  </React.StrictMode>
);

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

export default function App() {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');

  const { data: todos = [], isLoading, isError, error } = useQuery({
    queryKey: ['todos'],
    queryFn: async () => {
      const res = await fetch('/api/todos');
      if (!res.ok) throw new Error('Failed to fetch todos');
      return res.json();
    },
  });

  const mutation = useMutation({
    mutationFn: async (newText) => {
      const res = await fetch('/api/todos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: newText }),
      });
      if (!res.ok) throw new Error('Failed to create todo');
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const trimmed = text.trim();
    if (!trimmed) return;
    mutation.mutate(trimmed);
    setText('');
  };

  return (
    <div style={{ maxWidth: '480px', margin: '40px REDACTED', fontFamily: 'sans-serif' }}>
      <h1>Todo List</h1>

      <form onSubmit={handleSubmit} style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
        <input
          id="todo-input"
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Enter a new todo..."
          style={{ flex: 1, padding: '8px' }}
        />
        <button
          id="todo-submit"
          type="submit"
          disabled={mutation.isPending}
          style={{ padding: '8px 16px' }}
        >
          {mutation.isPending ? 'Adding...' : 'Add'}
        </button>
      </form>

      {isError && <p style={{ color: 'red' }}>Error: {error.message}</p>}
      {mutation.isError && (
        <p style={{ color: 'red' }}>Error: {mutation.error.message}</p>
      )}

      {isLoading ? (
        <p>Loading todos...</p>
      ) : (
        <ul id="todo-list" style={{ listStyle: 'none', padding: 0 }}>
          {todos.map((todo) => (
            <li key={todo.id} style={{ padding: '8px', borderBottom: '1px solid #eee' }}>
              {todo.text}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

